// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

import { forwardRef, useCallback, useEffect, useId, useRef, useState } from "react";
import type { PointerEvent as ReactPointerEvent, ReactNode } from "react";
import { AnimatePresence, MotionConfig, motion } from "framer-motion";
import type { PanInfo, Variants } from "framer-motion";
import {
  AlertCircle,
  AlertTriangle,
  BellOff,
  CheckCircle2,
  ChevronsDownUp,
  ChevronsUpDown,
  Info,
  MessageSquare,
  Trash2,
  X,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

/* ==========================================================================
   Types
   ========================================================================== */

export type NotificationType = "info" | "success" | "warning" | "error" | "message";

export interface NotificationItem {
  id: string;
  title: string;
  description?: string;
  /** Shown as written, for example "Just now" or "2 min ago". */
  timestamp?: string;
  type?: NotificationType;
  /** Replaces the default icon for the notification's type. */
  icon?: ReactNode;
}

export interface NotificationStackProps {
  /** The first item is the top card, so put the newest one first. */
  notifications: NotificationItem[];
  /** Called when one notification is dismissed, by its button or by swiping it away. */
  onDismiss: (id: string) => void;
  /** Called when "Clear all" is pressed. */
  onClearAll: () => void;
  title?: string;
  emptyMessage?: string;
  /** What opens the stack. "both" is the default. */
  expandOn?: "hover" | "click" | "both";
  /** How many cards peek out from behind the top one. Default 2. */
  maxPeek?: number;
  className?: string;
}

interface ExitCustom {
  /** 1 slides the card out to the right, -1 to the left, 0 fades it upward. */
  dir: -1 | 0 | 1;
}

// end of types


/* ==========================================================================
   Constants
   ========================================================================== */

const PEEK = 12; // how far each card behind the top one sticks out, in pixels
const SCALE_STEP = 0.05; // how much smaller each card behind is
const SWIPE_DISTANCE = 110; // how far you drag a card to dismiss it, in pixels
const SWIPE_SPEED = 520; // or how fast you flick it
const HOVER_OPEN_MS = 60;
const HOVER_CLOSE_MS = 240;

const SPRING = { type: "spring", stiffness: 380, damping: 34, mass: 0.9 } as const;

const TYPE_STYLES: Record<NotificationType, { icon: LucideIcon; className: string }> = {
  info: { icon: Info, className: "bg-blue-500/10 text-blue-600 dark:text-blue-400" },
  success: { icon: CheckCircle2, className: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400" },
  warning: { icon: AlertTriangle, className: "bg-amber-500/10 text-amber-600 dark:text-amber-400" },
  error: { icon: AlertCircle, className: "bg-rose-500/10 text-rose-600 dark:text-rose-400" },
  message: { icon: MessageSquare, className: "bg-violet-500/10 text-violet-600 dark:text-violet-400" },
};

// How a card leaves. The direction comes from AnimatePresence's `custom` prop.
const CARD_VARIANTS: Variants = {
  exit: (custom: ExitCustom) => ({
    opacity: 0,
    x: custom.dir * 320,
    y: custom.dir === 0 ? -10 : 0,
    scale: 0.92,
    transition: { duration: 0.26, ease: [0.4, 0, 0.2, 1] },
  }),
};

// end of constants


/* ==========================================================================
   Helpers
   ========================================================================== */

// Join class names, skipping anything falsy
function cn(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

// end of helpers


/* ==========================================================================
   NotificationCard
   ========================================================================== */

interface NotificationCardProps {
  item: NotificationItem;
  index: number;
  total: number;
  expanded: boolean;
  maxPeek: number;
  /** Height of the top card, used to keep the cards behind it the same size. */
  topHeight: number;
  onMeasure: (height: number) => void;
  onDismiss: (id: string, dir: -1 | 1) => void;
}

// forwardRef is needed because AnimatePresence's "popLayout" mode attaches a ref to each child
const NotificationCard = forwardRef<HTMLLIElement, NotificationCardProps>(function NotificationCard(
  { item, index, total, expanded, maxPeek, topHeight, onMeasure, onDismiss },
  forwardedRef
) {
  const elementRef = useRef<HTMLLIElement | null>(null);
  const isTop = index === 0;
  const interactive = expanded || isTop;

  const setRefs = useCallback(
    (node: HTMLLIElement | null) => {
      elementRef.current = node;
      if (typeof forwardedRef === "function") forwardedRef(node);
      else if (forwardedRef) forwardedRef.current = node;
    },
    [forwardedRef]
  );

  // The top card reports its height, so the cards behind it can match it
  useEffect(() => {
    const el = elementRef.current;
    if (!isTop || !el) return;

    onMeasure(el.offsetHeight);
    const observer = new ResizeObserver(() => onMeasure(el.offsetHeight));
    observer.observe(el);
    return () => observer.disconnect();
  }, [isTop, onMeasure]);

  // Where this card sits. Collapsed: tucked behind the card above. Expanded: a normal list item.
  const level = Math.min(index, maxPeek);
  const hidden = !expanded && index > maxPeek;
  const target = expanded
    ? { opacity: 1, y: 0, scale: 1 }
    : { opacity: hidden ? 0 : 1 - level * 0.18, y: level * PEEK, scale: 1 - level * SCALE_STEP };

  const tone = TYPE_STYLES[item.type ?? "info"];
  const Icon = tone.icon;

  const handleDragEnd = (_event: MouseEvent | TouchEvent | PointerEvent, info: PanInfo) => {
    if (Math.abs(info.offset.x) > SWIPE_DISTANCE || Math.abs(info.velocity.x) > SWIPE_SPEED) {
      onDismiss(item.id, info.offset.x < 0 ? -1 : 1);
    }
  };

  return (
    <motion.li
      ref={setRefs}
      layout="position"
      variants={CARD_VARIANTS}
      initial={{ opacity: 0, y: -28, scale: 0.94 }}
      animate={target}
      exit="exit"
      transition={SPRING}
      drag={interactive ? "x" : false}
      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.7}
      dragSnapToOrigin
      onDragEnd={handleDragEnd}
      aria-hidden={!interactive}
      style={{
        zIndex: total - index,
        // Growing from the bottom edge keeps the peeking strip the same size on every card
        transformOrigin: "bottom center",
        height: !expanded && !isTop && topHeight > 0 ? topHeight : undefined,
      }}
      className={cn(
        "relative w-full touch-pan-y select-none overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-lg shadow-black/5",
        !expanded && "col-start-1 row-start-1",
        interactive ? "pointer-events-auto cursor-grab active:cursor-grabbing" : "pointer-events-none"
      )}
    >
      <span aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 h-12 bg-gradient-to-b from-foreground/[0.04] to-transparent" />

      <div className="relative flex items-start gap-3 p-4">
        <span className={cn("mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl", tone.className)}>
          {item.icon ?? <Icon size={18} aria-hidden="true" />}
        </span>

        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-2">
            <p className="truncate text-sm font-semibold text-foreground">{item.title}</p>
            {item.timestamp && <time className="shrink-0 pt-0.5 text-[11px] text-muted-foreground">{item.timestamp}</time>}
          </div>
          {item.description && <p className="mt-0.5 line-clamp-3 text-sm leading-relaxed text-muted-foreground">{item.description}</p>}
        </div>

        <button
          type="button"
          data-dismiss
          tabIndex={interactive ? 0 : -1}
          aria-label={`Dismiss notification: ${item.title}`}
          onClick={(e) => {
            e.stopPropagation();
            onDismiss(item.id, 1);
          }}
          // Pressing the button must not start a drag
          onPointerDownCapture={(e: ReactPointerEvent<HTMLButtonElement>) => e.stopPropagation()}
          className="-mr-1 -mt-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <X size={14} aria-hidden="true" />
        </button>
      </div>

    </motion.li>
  );
});

// end of NotificationCard


/* ==========================================================================
   NotificationStack
   ========================================================================== */

export function NotificationStack({
  notifications,
  onDismiss,
  onClearAll,
  title = "Notifications",
  emptyMessage = "You're all caught up.",
  expandOn = "both",
  maxPeek = 2,
  className,
}: NotificationStackProps) {
  // ---- State ----
  const [hovered, setHovered] = useState(false); // the mouse is over the stack
  const [pinned, setPinned] = useState(false); // opened by a click, stays open until closed
  const [keyboardInside, setKeyboardInside] = useState(false); // focus is inside the list, from the keyboard
  const [topHeight, setTopHeight] = useState(0);
  const [exitCustom, setExitCustom] = useState<ExitCustom>({ dir: 1 });
  const [announcement, setAnnouncement] = useState("");
  // end of state

  // ---- Refs ----
  const rootRef = useRef<HTMLElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const hoverTimer = useRef<number | undefined>(undefined);
  const clearTimer = useRef<number | undefined>(undefined);
  const previousIds = useRef<string[]>(notifications.map((n) => n.id));
  // end of refs

  const headingId = useId();
  const listId = useId();
  const count = notifications.length;
  const canHover = expandOn !== "click";
  const canClick = expandOn !== "hover";
  const expanded = count > 1 && (pinned || (canHover && hovered) || keyboardInside);
  const peekCount = Math.min(Math.max(count - 1, 0), maxPeek);

  useEffect(
    () => () => {
      window.clearTimeout(hoverTimer.current);
      window.clearTimeout(clearTimer.current);
    },
    []
  );

  // ---- Opening and closing ----
  // A short delay on both ends stops the stack flickering as it grows under the mouse
  const handlePointerEnter = (e: ReactPointerEvent<HTMLElement>) => {
    if (!canHover || e.pointerType !== "mouse") return;
    window.clearTimeout(hoverTimer.current);
    hoverTimer.current = window.setTimeout(() => setHovered(true), HOVER_OPEN_MS);
  };

  const handlePointerLeave = (e: ReactPointerEvent<HTMLElement>) => {
    if (e.pointerType !== "mouse") return;
    window.clearTimeout(hoverTimer.current);
    hoverTimer.current = window.setTimeout(() => setHovered(false), HOVER_CLOSE_MS);
  };

  const collapse = useCallback(() => {
    setPinned(false);
    setHovered(false);
    setKeyboardInside(false);
  }, []);

  const handleToggle = () => {
    if (expanded) collapse();
    else setPinned(true);
  };

  // Clicking outside, or pressing Escape, closes a stack that was opened by a click
  useEffect(() => {
    if (!pinned) return;

    const onPointerDown = (e: PointerEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setPinned(false);
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") collapse();
    };

    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [pinned, collapse]);
  // end of opening and closing

  // ---- Dismissing ----
  const handleDismiss = useCallback(
    (id: string, dir: -1 | 1) => {
      const hadFocus = Boolean(listRef.current?.contains(document.activeElement));
      setExitCustom({ dir });
      onDismiss(id);

      // The button that had focus is about to disappear, so hand focus to a button that will stay
      if (hadFocus) requestAnimationFrame(() => toggleRef.current?.focus());
    },
    [onDismiss]
  );

  const handleClearAll = () => {
    window.clearTimeout(clearTimer.current);
    // Everything fades upward instead of sliding sideways
    setExitCustom({ dir: 0 });
    collapse();
    onClearAll();
    clearTimer.current = window.setTimeout(() => setExitCustom({ dir: 1 }), 800);
  };
  // end of dismissing

  // Screen readers hear about each new notification
  useEffect(() => {
    const added = notifications.filter((n) => !previousIds.current.includes(n.id));
    if (added.length > 0) setAnnouncement(`New notification: ${added[0].title}`);
    previousIds.current = notifications.map((n) => n.id);
  }, [notifications]);

  return (
    <MotionConfig reducedMotion="user">
      <section
        ref={rootRef}
        aria-labelledby={headingId}
        onPointerEnter={handlePointerEnter}
        onPointerLeave={handlePointerLeave}
        className={cn("w-full max-w-sm", className)}
      >
        {/* Header */}
        <div className="mb-3 flex items-center justify-between gap-3 px-1">
          <div className="flex items-center gap-2">
            <h2 id={headingId} className="text-sm font-semibold text-foreground">
              {title}
            </h2>
            {count > 0 && (
              <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium tabular-nums text-muted-foreground">
                {count}
                <span className="sr-only"> notifications</span>
              </span>
            )}
          </div>

          <div className="flex items-center gap-1.5">
            <AnimatePresence initial={false}>
              {expanded && (
                <motion.button
                  key="clear-all"
                  type="button"
                  onClick={handleClearAll}
                  initial={{ opacity: 0, x: 8 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 8 }}
                  transition={{ duration: 0.18 }}
                  className="inline-flex h-8 items-center gap-1.5 rounded-lg border border-border bg-card px-2.5 text-xs font-medium text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <Trash2 size={13} aria-hidden="true" />
                  Clear all
                </motion.button>
              )}
            </AnimatePresence>

            {count > 1 && (
              <button
                ref={toggleRef}
                type="button"
                onClick={handleToggle}
                aria-expanded={expanded}
                aria-controls={listId}
                aria-label={expanded ? "Collapse notifications" : `Show all ${count} notifications`}
                className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-border bg-card text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
              >
                {expanded ? <ChevronsDownUp size={15} aria-hidden="true" /> : <ChevronsUpDown size={15} aria-hidden="true" />}
              </button>
            )}
          </div>
        </div>

        {/* The cards. Collapsed, they share one grid cell and overlap. Expanded, they become a vertical list. */}
        <motion.ul
          ref={listRef}
          id={listId}
          layout
          role="list"
          onClick={() => {
            if (!expanded && canClick && count > 1) setPinned(true);
          }}
          onFocus={(e) => {
            // Only keyboard focus opens the stack. A mouse click should not trap it open.
            if (count > 1 && (e.target as HTMLElement).matches(":focus-visible")) setKeyboardInside(true);
          }}
          onBlur={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setKeyboardInside(false);
          }}
          animate={{ paddingBottom: expanded ? 0 : peekCount * PEEK }}
          transition={SPRING}
          className={cn("relative m-0 list-none p-0", expanded ? "flex flex-col gap-2.5" : "grid", !expanded && canClick && count > 1 && "cursor-pointer")}
        >
          <AnimatePresence initial={false} mode="popLayout" custom={exitCustom}>
            {notifications.map((item, index) => (
              <NotificationCard
                key={item.id}
                item={item}
                index={index}
                total={count}
                expanded={expanded}
                maxPeek={maxPeek}
                topHeight={topHeight}
                onMeasure={setTopHeight}
                onDismiss={handleDismiss}
              />
            ))}
          </AnimatePresence>
        </motion.ul>

        {/* Nothing to show */}
        <AnimatePresence>
          {count === 0 && (
            <motion.div
              key="empty"
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.25, delay: 0.15 }}
              className="flex flex-col items-center gap-2 rounded-2xl border border-dashed border-border px-6 py-10 text-center"
            >
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-muted text-muted-foreground">
                <BellOff size={18} aria-hidden="true" />
              </span>
              <p className="text-sm text-muted-foreground">{emptyMessage}</p>
            </motion.div>
          )}
        </AnimatePresence>

        <p className="sr-only" role="status" aria-live="polite">
          {announcement}
        </p>
      </section>
    </MotionConfig>
  );
}

export default NotificationStack;

// end of NotificationStack

